    public IReadOnlyList<string> GetCategories()
        => _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category)
        => _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id)
        => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        var recipe = GetById(recipeId);
        if (recipe is null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count + 12; // include seed ratings
        recipe.AverageRating = Math.Round(
            (_ratings[recipeId].Sum() + recipe.AverageRating * 12) / recipe.RatingCount, 1);
    }

    public Recipe AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

@using RecipeHub.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _displayRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0"
              title="Rate @star star(s)">
            ★
        </span>
    }
    <span class="rating-text">
        @if (_submitted)
        {
            <text>Thanks for rating!</text>
        }
        else
        {
            <text>(@AverageRating.ToString("0.0") avg · @RatingCount ratings)</text>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _hoverRating;
    private int _selectedRating;
    private bool _submitted;

    private int _displayRating => _hoverRating > 0 ? _hoverRating
        : _selectedRating > 0 ? _selectedRating
        : (int)Math.Round(AverageRating);

    private void Rate(int stars)
    {
        _selectedRating = stars;
        _submitted = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

@page "/"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>RecipeHub — Home</PageTitle>

<div class="hero">
    <h1>🍳 Welcome to RecipeHub</h1>
    <p class="lead">Discover and share delicious recipes from around the world.</p>
</div>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in RecipeService.GetCategories())
    {
        <a href="recipes/@category" class="category-card">
            <span class="category-icon">@GetCategoryIcon(category)</span>
            <span class="category-name">@category</span>
            <span class="category-count">@RecipeService.GetByCategory(category).Count recipes</span>
        </a>
    }
</div>

<div class="cta-section">
    <h3>Have a recipe to share?</h3>
    <p>Join our community and submit your favorite dishes.</p>
    <a href="submit" class="btn btn-primary btn-lg">Submit a Recipe</a>
</div>

@code {
    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/recipes/{Category}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@Category Recipes — RecipeHub</PageTitle>

<h1>@Category Recipes</h1>
<p><a href="/">← Back to categories</a></p>

@if (_recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in _recipes)
        {
            <a href="recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <p>@recipe.Description</p>
                <div class="recipe-meta">
                    <span class="stars">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                    <span>@recipe.AverageRating.ToString("0.0") · @recipe.RatingCount ratings</span>
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Components.Shared
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeHub</PageTitle>
    <h1>Recipe not found</h1>
    <p><a href="/">← Back to home</a></p>
}
else
{
    <PageTitle>@_recipe.Title — RecipeHub</PageTitle>

    <p><a href="recipes/@_recipe.Category">← Back to @_recipe.Category</a></p>

    <article class="recipe-detail">
        <h1>@_recipe.Title</h1>
        <p class="recipe-description">@_recipe.Description</p>

        <StarRating RecipeId="@_recipe.Id"
                    AverageRating="@_recipe.AverageRating"
                    RatingCount="@_recipe.RatingCount" />

        <section>
            <h2>🥘 Ingredients</h2>
            <ul class="ingredients-list">
                @foreach (var ingredient in _recipe.Ingredients)
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section>
            <h2>📝 Steps</h2>
            <ol class="steps-list">
                @foreach (var step in _recipe.Steps)
                {
                    <li>@step</li>
                }
            </ol>
        </section>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your culinary creations with the RecipeHub community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "<strong>@_title</strong>" has been added.
        <a href="recipe/@_createdId">View it here</a>.
    </div>
}

<EditForm FormName="submit-recipe" Model="_model" OnValidSubmit="HandleSubmit">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
            <option value="">— Select a category —</option>
            <option value="Italian">Italian</option>
            <option value="Indian">Indian</option>
            <option value="Mexican">Mexican</option>
            <option value="Desserts">Desserts</option>
            <option value="Other">Other</option>
        </InputSelect>
    </div>

    <div class="mb-3">
        <label for="description" class="form-label">Short Description</label>
        <InputTextArea id="description" class="form-control" @bind-Value="_model.Description" rows="2"
                       placeholder="A brief description of your dish" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" @bind-Value="_model.IngredientsText" rows="5"
                       placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" @bind-Value="_model.StepsText" rows="5"
                       placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients..." />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private string _title = string.Empty;
    private int _createdId;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_model.Title) || string.IsNullOrWhiteSpace(_model.Category))
            return;

        var ingredients = _model.IngredientsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var steps = _model.StepsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var recipe = RecipeService.AddRecipe(
            _model.Title, _model.Category, _model.Description ?? string.Empty, ingredients, steps);

        _title = recipe.Title;
        _createdId = recipe.Id;
        _submitted = true;
        _model = new();
    }

    private class RecipeFormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Category { get; set; } = string.Empty;
        public string? Description { get; set; }
        public string IngredientsText { get; set; } = string.Empty;
        public string StepsText { get; set; } = string.Empty;
    }
}

