using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A traditional Neapolitan pizza with fresh mozzarella and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10–12 minutes until the crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil."
                ],
                AverageRating = 4.5, RatingCount = 12
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Crisp pancetta in a skillet over medium heat.",
                    "Whisk eggs with grated Pecorino and plenty of black pepper.",
                    "Drain pasta, reserving 1 cup of pasta water.",
                    "Toss hot pasta with pancetta, then quickly stir in the egg mixture off heat.",
                    "Add pasta water a splash at a time until creamy. Serve immediately."
                ],
                AverageRating = 4.8, RatingCount = 24
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = [
                    "Marinate chicken in yogurt, garam masala, and salt for at least 1 hour.",
                    "Grill or broil chicken until charred and cooked through.",
                    "Sauté onion, garlic, and ginger in a large pan.",
                    "Add tomato sauce and spices; simmer for 15 minutes.",
                    "Stir in heavy cream, then add the grilled chicken pieces.",
                    "Simmer for 10 more minutes. Serve over basmati rice."
                ],
                AverageRating = 4.6, RatingCount = 18
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Biryani", Category = "Indian",
                Description = "Fragrant layered rice dish with mixed vegetables and aromatic spices.",
                Ingredients = ["Basmati rice", "Mixed vegetables", "Onions", "Biryani spice mix", "Saffron", "Yogurt", "Ghee", "Mint leaves"],
                Steps = [
                    "Soak basmati rice for 30 minutes, then par-boil until 70% cooked.",
                    "Fry sliced onions in ghee until deeply golden.",
                    "Cook mixed vegetables with yogurt and biryani spices.",
                    "Layer rice and vegetable mixture in a heavy pot.",
                    "Top with saffron milk, fried onions, and mint leaves.",
                    "Seal the pot and cook on low heat (dum) for 25 minutes."
                ],
                AverageRating = 4.3, RatingCount = 9
            },
            new Recipe
            {
                Id = 5, Title = "Tacos al Pastor", Category = "Mexican",
                Description = "Marinated pork tacos with pineapple, inspired by Lebanese shawarma.",
                Ingredients = ["Pork shoulder", "Dried chiles", "Pineapple", "Corn tortillas", "Onion", "Cilantro", "Lime"],
                Steps = [
                    "Blend dried chiles, pineapple juice, and spices into a smooth marinade.",
                    "Marinate thinly sliced pork for at least 4 hours.",
                    "Cook pork on a hot skillet or grill until caramelized.",
                    "Grill pineapple slices until charred, then chop.",
                    "Warm corn tortillas on a dry skillet.",
                    "Assemble tacos with pork, pineapple, diced onion, cilantro, and lime juice."
                ],
                AverageRating = 4.7, RatingCount = 15
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh avocado dip with lime, cilantro, and a kick of jalapeño.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = [
                    "Halve and pit ripe avocados; scoop flesh into a bowl.",
                    "Mash with a fork to desired consistency (chunky or smooth).",
                    "Stir in lime juice, diced onion, chopped cilantro, and minced jalapeño.",
                    "Fold in diced tomato gently.",
                    "Season with salt to taste. Serve immediately with tortilla chips."
                ],
                AverageRating = 4.4, RatingCount = 20
            },
            new Recipe
            {
                Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Individual warm cakes with a molten chocolate center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = [
                    "Preheat oven to 425°F (220°C). Butter and flour four ramekins.",
                    "Melt chocolate and butter together; let cool slightly.",
                    "Whisk eggs and sugar until thick and pale.",
                    "Fold chocolate mixture into the eggs, then fold in flour.",
                    "Divide batter among ramekins. Bake for 12–14 minutes.",
                    "Let rest 1 minute, then invert onto plates. Serve immediately."
                ],
                AverageRating = 4.9, RatingCount = 30
            },
            new Recipe
            {
                Id = 8, Title = "Tiramisu", Category = "Desserts",
                Description = "Classic Italian layered dessert with coffee-soaked ladyfingers and mascarpone.",
                Ingredients = ["Ladyfingers", "Espresso", "Mascarpone", "Eggs", "Sugar", "Cocoa powder", "Marsala wine"],
                Steps = [
                    "Brew espresso and let it cool. Mix with Marsala wine.",
                    "Separate eggs. Beat yolks with sugar until pale and thick.",
                    "Fold mascarpone into the yolk mixture until smooth.",
                    "Whip egg whites to stiff peaks; fold into mascarpone mixture.",
                    "Dip ladyfingers briefly in espresso and layer in a dish.",
                    "Spread mascarpone cream over ladyfingers. Repeat layers.",
                    "Refrigerate for at least 4 hours. Dust with cocoa before serving."
                ],
                AverageRating = 4.7, RatingCount = 22
            }
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
        => _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category)
        => _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id)
        => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        var recipe = GetById(recipeId);
        if (recipe is null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count + 12; // include seed ratings
        recipe.AverageRating = Math.Round(
            (_ratings[recipeId].Sum() + recipe.AverageRating * 12) / recipe.RatingCount, 1);
    }

    public Recipe AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

@using RecipeHub.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _displayRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0"
              title="Rate @star star(s)">
            ★
        </span>
    }
    <span class="rating-text">
        @if (_submitted)
        {
            <text>Thanks for rating!</text>
        }
        else
        {
            <text>(@AverageRating.ToString("0.0") avg · @RatingCount ratings)</text>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _hoverRating;
    private int _selectedRating;
    private bool _submitted;

    private int _displayRating => _hoverRating > 0 ? _hoverRating
        : _selectedRating > 0 ? _selectedRating
        : (int)Math.Round(AverageRating);

    private void Rate(int stars)
    {
        _selectedRating = stars;
        _submitted = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

