.star-rating {
    display: flex;
    align-items: center;
    gap: 2px;
    margin: 1rem 0;
}

.star-rating .star {
    font-size: 1.8rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s;
    user-select: none;
}

.star-rating .star:hover,
.star-rating .star.filled {
    color: #f5a623;
}

.star-rating .rating-text {
    margin-left: 0.75rem;
    font-size: 0.9rem;
    color: #6c757d;
}

