+    padding: 2rem;
+    background: #f8f9fa;
+    border-radius: 10px;
+    margin-top: 1rem;
+}
+
+.recipe-list {
+    display: flex;
+    flex-direction: column;
+    gap: 1rem;
+}
+
+.recipe-card {
+    display: block;
+    padding: 1.2rem;
+    background: #fff;
+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+    text-decoration: none;
+    color: inherit;
+    transition: box-shadow 0.2s;
+}
+
+.recipe-card:hover {
+    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
+    text-decoration: none;
+    color: inherit;
+}
+
+.recipe-card h3 {
+    margin: 0 0 0.3rem;
+    font-size: 1.15rem;
+}
+
+.recipe-card p {
+    margin: 0 0 0.5rem;
+    color: #555;
+    font-size: 0.95rem;
+}
+
+.recipe-meta {
+    display: flex;
+    gap: 0.75rem;
+    font-size: 0.9rem;
+    color: #6c757d;
+}
+
+.recipe-meta .stars {
+    color: #f5a623;
+}
+
+.recipe-detail {
+    max-width: 700px;
+}
+
+.recipe-description {
+    font-size: 1.1rem;
+    color: #555;
+    margin-bottom: 1rem;
+}
+
+.ingredients-list li, .steps-list li {
+    margin-bottom: 0.4rem;
+}
+
+.steps-list li {
+    margin-bottom: 0.6rem;
+    line-height: 1.5;
+}
+
+/* Star rating widget */
+.star-rating {
+    display: flex;
+    align-items: center;
+    gap: 2px;
+    margin: 1rem 0;
+}
+
+.star-rating .star {
+    font-size: 1.8rem;
+    color: #ccc;
+    cursor: pointer;
+    transition: color 0.15s;
+    user-select: none;
+}
+
+.star-rating .star:hover,
+.star-rating .star.filled {
+    color: #f5a623;
+}
+
+.star-rating .rating-text {
+    margin-left: 0.75rem;
+    font-size: 0.9rem;
+    color: #6c757d;
+}
+
